import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
import '../api/gaon_api.dart';

class OrderRecoveryCard extends StatefulWidget{final String orderId;const OrderRecoveryCard({super.key,required this.orderId});@override State<OrderRecoveryCard> createState()=>_OrderRecoveryCardState();}
class _OrderRecoveryCardState extends State<OrderRecoveryCard>{Map<String,dynamic>? data;String? error;Future<Map<String,String>> _headers()async{final p=await SharedPreferences.getInstance();final t=p.getString('token');return{'Content-Type':'application/json',if(t!=null)'Authorization':'Bearer $t'};}@override void initState(){super.initState();load();}Future<void> load()async{try{final r=await http.get(Uri.parse('${GaonApi.baseUrl}/orders/${widget.orderId}/recovery'),headers:await _headers()).timeout(GaonApi.timeout);if(r.statusCode<200||r.statusCode>=300)throw Exception('Recovery options unavailable');if(mounted)setState((){data=Map<String,dynamic>.from(jsonDecode(r.body));error=null;});}catch(e){if(mounted)setState(()=>error='$e'.replaceFirst('Exception: ',''));}}Future<void> support()async{final description=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Get order help'),content:TextField(controller:description,minLines:3,maxLines:6,decoration:const InputDecoration(labelText:'What happened?')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Create ticket'))]));if(ok!=true||description.text.trim().length<5)return;try{final r=await http.post(Uri.parse('${GaonApi.baseUrl}/support/tickets'),headers:await _headers(),body:jsonEncode({'subject':'Order support','description':description.text.trim(),'order_id':widget.orderId,'delivery_id':null})).timeout(GaonApi.timeout);if(r.statusCode<200||r.statusCode>=300)throw Exception('Could not create support ticket');if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Support ticket created.')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e'.replaceFirst('Exception: ',''))));}}@override Widget build(BuildContext context){if(error!=null||data?['has_recovery_action']!=true)return const SizedBox.shrink();final actions=(data!['actions'] as List? ?? const []).map((e)=>Map<String,dynamic>.from(e as Map)).toList();final hasSupport=actions.any((a)=>a['code']=='contact_support');return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Row(children:[Icon(Icons.support_agent),SizedBox(width:8),Text('What can I do now?',style:TextStyle(fontWeight:FontWeight.w700))]),const SizedBox(height:6),Text(actions.map((a)=>'${a['label']}').join(' • '),style:Theme.of(context).textTheme.bodySmall),if(hasSupport)...[const SizedBox(height:8),OutlinedButton.icon(onPressed:support,icon:const Icon(Icons.help_outline),label:const Text('Get order help'))]])));}}
